/* Configuration authoring mock; all edits live only in this document's memory. */
(() => {
  'use strict';
  const C=window.ConfigurationPrototype, root=document.querySelector('#configuration-root');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pages={systems:['系统配置','决定用户可以选择哪些系统，以及常用的检查问题。'],environments:['环境配置','为系统配置可用环境、默认模型与只读资源范围。'],models:['模型配置','管理对话中的模型名称，以及对应的执行连接与 Agent。'],permissions:['权限配置','按成员角色限定系统、环境、模型和资料访问。']};
  const selections={systems:'orders',environments:'orders-test',models:'general',permissions:'tester'};
  const providers={control:'总控适配器',direct:'受控 ACP 直连'};
  let page='systems',notice='',trigger;
  const btn=(id,text,cls='')=>`<button type="button" data-admin="${id}" class="${cls}">${text}</button>`;
  const text=(label,field,value,extra='')=>`<label class="admin-field">${label}<input data-field="${field}" value="${esc(value)}" ${extra}></label>`;
  const toggle=(label,field,value,help='')=>`<label class="admin-toggle"><span>${label}${help?`<small>${help}</small>`:''}</span><input type="checkbox" data-field="${field}" ${value?'checked':''}></label>`;
  const select=(label,field,value,items)=>`<label class="admin-field">${label}<select data-field="${field}">${items.map(([id,name])=>`<option value="${id}" ${id===value?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
  const group=()=>page==='permissions'?'roles':page;
  const selected=()=>C.draft()[group()].find(x=>x.id===selections[page]);
  function systems(x){return `<h2>用户看到的系统</h2><p class="admin-muted">固定流程：只读问题检查 · 示例。用户通过对话发起，不需要配置流程。</p>${text('系统名称','name',x.name,'maxlength="40"')}${text('负责团队','owner',x.owner)}${text('用途说明','description',x.description)}${toggle('在用户端提供此系统','enabled',x.enabled,'停用后不再接受新的检查，既有记录保留。')}<h3>常用检查问题</h3><p class="admin-muted">显示在用户输入框上方，点击后填入问题。</p>${['核对报表与明细差异','排查接口异常','分析错误日志'].map(p=>`<label class="admin-check"><input type="checkbox" data-prompt="${p}" ${x.prompts.includes(p)?'checked':''}>${p}</label>`).join('')}`;}
  function environments(x){const d=C.draft(),sys=d.systems.find(s=>s.id===x.system);return `<h2>${esc(sys.name)} / 环境设置</h2>${select('所属系统','system',x.system,d.systems.map(s=>[s.id,s.name]))}${text('环境名称','name',x.name,'maxlength="40"')}${select('默认模型','defaultModel',x.defaultModel,d.models.map(m=>[m.id,m.name+(m.enabled?'':' · 已停用')]))}${toggle('在用户端提供此环境','enabled',x.enabled)}<h3>只读资源范围</h3><div class="admin-resource"><span>代码</span><strong>${esc(x.system)} / 固定部署版本</strong><span>日志</span><strong>${esc(x.name)} / 当前问题时间范围</strong><span>数据</span><strong>脱敏只读查询 / 限定报表和明细</strong><span>文件</span><strong>本会话附件 / 经授权的检查产物</strong></div><p class="admin-muted">以上为合成范围说明。资源映射与真实执行身份待接入时配置；原型不保存连接串或凭据。</p><div class="admin-note">同一个问题会话固定系统和环境。修改环境默认模型，只影响之后新建的会话；不会替换正在执行的拥有者。</div>`;}
  function models(x){return `<h2>用户端模型选项</h2>${text('显示名称','name',x.name,'maxlength="40"')}${select('执行连接','provider',x.provider,Object.entries(providers))}<div class="admin-resource"><span>Agent</span><strong>${esc(x.agent)}</strong><span>实际模型 / 能力</span><strong>未知 · 尚未发现和验证</strong><span>允许的操作</span><strong>合成只读演示</strong></div>${toggle('在用户端提供此模型预设','enabled',x.enabled,'仅对已获权限的角色可见。')}<div class="admin-note">这是一项示例预设，不代表真实模型已可用。正式产品只允许将执行器已发现、确认且满足策略的模型投入使用。</div><details class="admin-details"><summary>执行连接与能力诊断</summary><p>总控和受控 ACP 直连都通过 ExecutionProvider。配置改变不迁移既有执行；能力未知、不匹配或审批桥接缺失时阻断真实执行。</p><a href="#connections">查看连接契约演练 ↗</a></details>`;}
  function permissions(x){const d=C.draft();return `<h2>${esc(x.name)}的使用范围</h2><h3>系统与环境</h3><div class="admin-check-grid">${d.environments.map(env=>`<label class="admin-check"><input type="checkbox" data-grant="environments" value="${env.id}" ${x.environments.includes(env.id)?'checked':''}>${esc(d.systems.find(s=>s.id===env.system).name)} / ${esc(env.name)}</label>`).join('')}</div><h3>可选模型</h3>${d.models.map(m=>`<label class="admin-check"><input type="checkbox" data-grant="models" value="${m.id}" ${x.models.includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}<h3>资料访问</h3>${toggle('添加附件','attachments',x.attachments,'原型只展示文件名；正式上传和内容读取分别鉴权。')}${toggle('下载检查文件','download',x.download,'对每份产物重新鉴权；本页仅配置和预览。')}${toggle('查看本人历史对话','history',x.history,'不包含他人的会话。原型未接入真实身份。')}${toggle('查看执行事件','events',x.events,'事件与诊断不是公开数据；本页仅配置和预览。')}<h3>审批与用量约束</h3>${toggle('允许确认本人会话的只读计划','canApproveRead',x.canApproveRead,'不包含写入或替他人批准；未授权时交由责任人。')}${text('审批责任人','approver',x.approver)}<div class="admin-two">${text('单轮调用上限（示例）','maxCalls',x.maxCalls,'type="number" min="1" max="100"')}${text('并发上限（示例）','concurrency',x.concurrency,'type="number" min="1" max="5"')}</div><p class="admin-muted">固定只读策略；具体操作执行前确认。受控写入不在本轮范围。数量与费用需后端落实，这里不声称已硬性限制。</p>`;}
  function preview(){const v=C.visible(C.draft()),rows=[['系统',v.systems.map(x=>x.name).join('、')||'无可用系统'],['环境',v.environments.map(x=>x.name).filter((x,i,a)=>a.indexOf(x)===i).join('、')||'无可用环境'],['模型',v.models.map(x=>x.name).join('、')||'无可用模型'],['附件',v.role.attachments?'允许添加':'不可添加'],['文件下载',v.role.download?'允许（仍需逐项授权）':'不允许'],['历史 / 事件',`${v.role.history?'本人历史':'不提供历史'} / ${v.role.events?'允许事件':'不提供事件'}`]];return `<h2>用户端预览</h2><label class="admin-field">预览身份<select id="admin-preview-role">${C.draft().roles.map(r=>`<option value="${r.id}" ${C.role()===r.id?'selected':''}>${r.name}</option>`).join('')}</select></label><p class="admin-muted">下方展示草稿效果。对话读取已应用配置；身份切换仅用于离线评审。</p><dl>${rows.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><a class="admin-preview-link" href="#chat">返回用户对话 ↗</a><div class="admin-note">用户只选择已配置、已获权限的选项，无需理解后端或权限规则。</div>`;}
  function render(next=page,focus=false){
    if(window.ServiceDesignPrototype?.has(next)){window.ServiceDesignPrototype.render(next,focus);return;}
    root.dataset.mode='configuration';page=pages[next]?next:'systems';const d=C.draft();if(!selected())selections[page]=d[group()][0].id;const x=selected(),items=d[group()];
    root.innerHTML=`<aside class="admin-sidebar"><a class="admin-brand" href="#admin-systems">◈ 平台管理</a><a class="admin-back" href="#chat">← 返回用户对话</a><div class="admin-nav-title">对话配置</div><nav class="admin-config-nav">${Object.entries(pages).map(([id,[title]])=>`<a href="#admin-${id}" ${page===id?'aria-current="page"':''}>${title}</a>`).join('')}</nav><div class="admin-nav-title service-nav-title">接入与治理</div><nav class="admin-service-nav">${Object.entries(window.ServiceDesignPrototype.pages).map(([id,[name]])=>`<a href="#admin-${id}">${name}</a>`).join('')}</nav><div class="admin-secondary"><a href="#contract">设计与契约评审 ↗</a><a href="#approval">审批恢复演练 ↗</a><small>初始设计 · 离线配置<br>刷新清空全部模拟改动</small></div></aside><main class="admin-main"><header class="admin-heading"><div><div class="admin-eyebrow">平台管理 / 对话配置</div><h1 tabindex="-1">${pages[page][0]}</h1><p>${pages[page][1]}</p></div><span class="admin-badge">合成配置管理员</span></header><div class="admin-toolbar"><span id="admin-draft-status"></span><div>${btn('discard','放弃草稿')}${btn('publish','预览并应用','admin-primary')}</div></div><div id="admin-feedback" role="status" aria-live="polite">${esc(notice)}</div><div class="admin-columns"><section class="admin-editor"><div class="admin-records" aria-label="配置记录">${page!=='permissions'?btn('add','＋ 新增'): ''}${items.map(i=>`<button data-record="${i.id}" ${i.id===x.id?'aria-pressed="true"':''}>${esc(page==='environments'?d.systems.find(s=>s.id===i.system).name+' / '+i.name:i.name)}${i.enabled===false?'<span>已停用</span>':''}</button>`).join('')}</div><div class="admin-form">${({systems,environments,models,permissions})[page](x)}</div></section><aside class="admin-preview">${preview()}</aside></div><details class="admin-audit"><summary>本次演示的配置记录（${C.audit().length}）</summary>${C.audit().length?C.audit().map(a=>`<p>配置修订 ${a.revision} · ${esc(a.actor)} · ${esc(a.at)}<br>${esc(a.changes.join('；'))}</p>`).join(''):'<p>暂无应用记录。草稿尚未影响用户对话。</p>'}</details></main><dialog id="admin-dialog" aria-labelledby="admin-dialog-title"></dialog>`;
    updatePreview();if(focus)root.querySelector('h1').focus();
    root.querySelector('#admin-dialog').addEventListener('cancel',()=>setTimeout(()=>trigger?.focus(),0));
  }
  function updatePreview(){root.querySelector('#admin-draft-status').textContent=`已应用配置修订 ${C.current().revision} · ${C.changes().length?'有 '+C.changes().length+' 项未应用改动':'草稿与已应用配置一致'}`;root.querySelector('.admin-preview').innerHTML=preview();}
  root.addEventListener('input',e=>{if(root.dataset.mode==='service')return;if(!e.target.dataset.field||e.target.type==='checkbox'||e.target.tagName==='SELECT')return;const value=e.target.type==='number'?Number(e.target.value):e.target.value;selected()[e.target.dataset.field]=value;updatePreview();});
  root.addEventListener('change',e=>{if(root.dataset.mode==='service')return;
    if(e.target.dataset.field&&e.target.type!=='checkbox'&&e.target.tagName!=='SELECT')return;
    const x=selected();
    if(e.target.dataset.field){x[e.target.dataset.field]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(e.target.dataset.field==='provider')x.agent=x.provider==='control'?'示例 Agent A':'示例 Agent B';}
    if(e.target.dataset.prompt)x.prompts=e.target.checked?[...new Set([...x.prompts,e.target.dataset.prompt])]:x.prompts.filter(p=>p!==e.target.dataset.prompt);
    if(e.target.dataset.grant){const key=e.target.dataset.grant;x[key]=e.target.checked?[...new Set([...x[key],e.target.value])]:x[key].filter(v=>v!==e.target.value);}
    if(e.target.id==='admin-preview-role')C.setRole(e.target.value);
    render();
  });
  root.addEventListener('click',e=>{if(root.dataset.mode==='service')return;
    const b=e.target.closest('button');if(!b)return;
    if(b.dataset.admin==='add'){const d=C.draft(),id='demo-'+group()+'-'+(d[group()].length+1);let item;if(page==='systems')item={id,name:'新系统 '+(d.systems.length+1),owner:'待指定团队',description:'',enabled:false,prompts:[]};if(page==='environments')item={id,system:d.systems[0].id,name:'新环境 '+(d.environments.length+1),enabled:false,defaultModel:d.models[0].id};if(page==='models')item={id,name:'新模型预设 '+(d.models.length+1),provider:'control',agent:'示例 Agent A',enabled:false};if(item){d[group()].push(item);selections[page]=id;render();}return;}
    if(b.dataset.record){selections[page]=b.dataset.record;render();return;}
    const dialog=root.querySelector('#admin-dialog');
    if(b.dataset.admin==='publish'){
      const errors=C.errors();if(errors.length||!C.changes().length){notice=errors.join(' ')||'没有待应用的改动。';root.querySelector('#admin-feedback').textContent=notice;return;}
      trigger=b;dialog.innerHTML=`<h2 id="admin-dialog-title">应用这份演示配置？</h2><ul>${C.changes().map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p>新对话读取新配置。已有会话的环境和执行配置快照不变；停用和撤权在下一步检查时阻断。不会调用真实资源。</p><div class="admin-dialog-actions">${btn('cancel','继续编辑')}${btn('confirm','应用到离线演示','admin-primary')}</div>`;dialog.showModal();
    }
    if(b.dataset.admin==='discard'){trigger=b;dialog.innerHTML=`<h2 id="admin-dialog-title">放弃全部未应用改动？</h2><p>四个配置页面的草稿恢复为已应用配置。</p><div class="admin-dialog-actions">${btn('cancel','继续编辑')}${btn('confirm-discard','放弃草稿')}</div>`;dialog.showModal();}
    if(b.dataset.admin==='cancel'){dialog.close();trigger?.focus();}
    if(b.dataset.admin==='confirm'){const result=C.publish();notice=result.ok?'已应用到离线演示。可返回用户对话查看可选项。':result.errors.join(' ');dialog.close();render(page,true);}
    if(b.dataset.admin==='confirm-discard'){C.discard();notice='已放弃草稿，已应用配置未改变。';dialog.close();render(page,true);}
  });
  window.AdminPrototype={render};
})();
